d=property.getter
class Fake:
 @property
 def __class__(self):
  print("advertised")
  return property
 def __getattribute__(self,name):
  print("read")
  return object.__getattribute__(self,name)
d.__get__(Fake())

p=property()
d=property.getter
class Owner:
 def __getattribute__(self,name): raise ValueError("read")
 def __bool__(self): raise ValueError("truth")
print(d.__get__(None,Owner()) is d)
print(d.__get__(p,Owner()).__self__ is p)

